return ['domain'=>NULL,'plural-forms'=>'nplurals=6; plural=n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 && n%100<=99 ? 4 : 5;','language'=>'ar','project-id-version'=>'WPGlobus Multilingual','pot-creation-date'=>'2026-02-01 02:55+0000','po-revision-date'=>'2015-09-03 17:28+0000','messages'=>['Guide'=>'الدليل','WPGlobus Help Desk'=>'WPGlobus دائرة المساعدة','Add-ons'=>'الإضافات','Quick Start'=>'بداية سريعة','FAQ'=>'أسئلة متداولة','Attention: the Multibyte String PHP extension (`mbstring`) is not loaded!'=>'إنتباه: سلسلة البايت المتعدد إضافة PHP (mbstring) غير مُحمل!','The mbstring extension is required for the full UTF-8 compatibility and better performance. Without it, some parts of WordPress and WPGlobus may function incorrectly. Please contact your hosting company or systems administrator.'=>'إضافة الـ"mbstring" مطلوبة من أجل دعم UTF-8 الكامل و أداء أفضل. من غيرها، بعض الأجزاء من  WordPress و WPGlobus ربما لن تعمل جيداً. من فضلك إتصل بشركة الإستضافة الخاصة بك أو مدير النظام.','Go to WPGlobus Settings'=>'إذهب إلي إعدادت WPGlobus ','Easy as 1-2-3:'=>'سهل مثل 1-2-3:','Go to WPGlobus admin menu and choose the countries / languages;'=>'إذهب إلي قائمة المدير الخاصة بـWPGlobus وإختر البلاد/اللغة;','Enter the translations to the posts, pages, categories, tags and menus using a clean and simple interface.'=>'أدخل الترجمة إلي المنشورات، الصفح، الأقسام، الإشارات و القوائم مستخدماً واجهة بسيطة ونظيفة.','Switch languages at the front-end using a drop-down menu with language names and country flags.'=>'غير اللغة في الواجهة بإستخدام القائمة المنسدلة مع أسماء اللغات و أعلام الدول.','Links:'=>'الراوبط:','FAQs'=>'الأسئلة المتكررة','Contact Us'=>'إتصل بنا','Please give us 5 stars!'=>'من فضلك أعطنا 5 نجوم!','WPGlobus does not translate texts automatically!'=>'WPGlobus  لا يُترجم النصوص تلقائياً!','There are many translation companies and individual translators who can help you write and proofread the texts.'=>'هناك شركات ترجمة كثيرة و مترجمين مستقلين يمكنهم مساعدتك في ترجمة وتصحيح الأخطاء في نصوصك.','When you choose a translator, please look at their native language, country of residence, specialization and knowledge of WordPress.'=>'حينما تختر مترجماً، من فضلك أنظر إلي لغتهم الأم، بلد المعيشة، التخصص ومعرفتة بـ WordPress.','Important notes:'=>'ملاحظات هامة:','WPGlobus only supports the localization URLs in the form of <code>example.com/xx/page/</code>. We do not plan to support subdomains <code>xx.example.com</code> and language queries <code>example.com?lang=xx</code>.'=>'WPGlobus يدعم فقط ترجمة الروابط في الصيغة<code>example.com/xx/page/</code>. نحن لا ننوي دعم النطاقات الفرعية<code>xx.example.com</code> وعلامات اللغة <code>example.com?lang=xx</code>.','Some themes and plugins are <strong>not multilingual-ready</strong>.'=>'بعض الثيمات و الإضافات هي<strong>ليس لديها لغات متنوعة</strong>.','They might display some texts with no translation, or with all languages mixed together.'=>'هذا ربما يظهر بعض الكتابات بدون ترجمة، أو مع كل اللغات مختلطة.','Please contact the theme / plugin author. If they are unable to assist, consider %1$s hiring the WPGlobus Team %2$s to write a custom code for you.'=>'من فضلك تواصل مع مالك الإضافة أو الثيم. إذا كانوا لا يستطيعوا المساعدة، فكر في %s تأجير فريق WPGlobus%s لكي يكتب كود مخصص لك.','Add'=>'إضافة','WPGlobus is a family of WordPress plugins assisting you in making multilingual WordPress blogs and sites.'=>'WPGlobus هي عائلة من إضافات ووردبريس يساعد في جعل المواقع و المدونات متعددة اللغة.','Remove the WPGlobus settings (not recommended)'=>'إمسح إعدادات WPGlobus (غير مُفضل)','Clean-up Tool'=>'أداة التنظيف','WARNING: this operation is non-reversible. It is strongly recommended that you backup your database before proceeding.'=>'تحذير: العملية لا يمكن الرجوع عنها. يُفضل بشدة أن تعمل نسخة إحتياطية لقاعدة البيانات قبل المتابعة.','You have been warned...'=>'لقد تم تحذيرك...','YES, I CONFIRM'=>'أجل، أنا أؤكد','Default'=>'الأفتراضي','Section'=>'قسم','WPGlobus'=>'WPGlobus','WPGlobus Settings'=>